CREATE OR REPLACE FUNCTION suikan.metrics(r jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$ SELECT jsonb_build_object('extract',jsonb_build_object('started',coalesce((r->>'extract_started')::bigint,0),'succeeded',coalesce((r->>'extract_succeeded')::bigint,0),'failed',coalesce((r->>'extract_failed')::bigint,0),'cancelled',coalesce((r->>'extract_cancelled')::bigint,0)),'summary',jsonb_build_object('started',coalesce((r->>'summary_started')::bigint,0),'succeeded',coalesce((r->>'summary_succeeded')::bigint,0),'failed',coalesce((r->>'summary_failed')::bigint,0),'cancelled',coalesce((r->>'summary_cancelled')::bigint,0)),'started',coalesce((r->>'extract_started')::bigint,0)+coalesce((r->>'summary_started')::bigint,0),'succeeded',coalesce((r->>'extract_succeeded')::bigint,0)+coalesce((r->>'summary_succeeded')::bigint,0),'failed',coalesce((r->>'extract_failed')::bigint,0)+coalesce((r->>'summary_failed')::bigint,0),'cancelled',coalesce((r->>'extract_cancelled')::bigint,0)+coalesce((r->>'summary_cancelled')::bigint,0)) $$;
CREATE OR REPLACE FUNCTION suikan.record(i text,v text,days text[]) RETURNS void LANGUAGE plpgsql AS $$
DECLARE first text; last text; previous record;
BEGIN
 SELECT min(x),max(x) INTO first,last FROM unnest(days) x;
 IF first IS NULL THEN RETURN; END IF;
 SELECT * INTO previous FROM suikan.installations WHERE id=i;
 IF NOT FOUND OR first<previous.first_day OR last>previous.last_day OR (last>=previous.last_day AND v<>previous.app_version) THEN
  INSERT INTO suikan.installations AS t VALUES(i,first,last,v) ON CONFLICT(id) DO UPDATE SET
   first_day=least(t.first_day,excluded.first_day),last_day=greatest(t.last_day,excluded.last_day),
   app_version=CASE WHEN excluded.last_day>=t.last_day THEN excluded.app_version ELSE t.app_version END;
 END IF;
 INSERT INTO suikan.active(day,id) SELECT DISTINCT x,i FROM unnest(days) x
  WHERE NOT EXISTS(SELECT 1 FROM suikan.active a WHERE a.day=x AND a.id=i) ON CONFLICT DO NOTHING;
END $$;
CREATE OR REPLACE FUNCTION suikan.rpc(action text,p jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE i text:=p->>'id'; v text:=p->>'version'; today text:=p->>'today'; days text[]; r jsonb; old jsonb;
 incoming bigint[]; delta bigint[]; n integer; result jsonb; start text; q text; lim integer; off integer;
BEGIN
 IF action='health' THEN
  PERFORM id FROM suikan.installations LIMIT 1; PERFORM id FROM suikan.operation_totals LIMIT 1;
  RETURN jsonb_build_object('ok',true);
 ELSIF action IN ('access','ingest','changeAccess') THEN
  PERFORM pg_advisory_xact_lock(hashtextextended(i,0));
  IF action='changeAccess' THEN
   INSERT INTO suikan.installation_access(id,enabled,reason)
    SELECT i,CASE WHEN (p->>'enabled')::boolean THEN 1 ELSE 0 END,
     CASE WHEN (p->>'enabled')::boolean THEN '' ELSE btrim(p->>'reason') END
    WHERE EXISTS(SELECT 1 FROM suikan.installations WHERE id=i)
    ON CONFLICT(id) DO UPDATE SET enabled=excluded.enabled,reason=excluded.reason;
   GET DIAGNOSTICS n=ROW_COUNT; RETURN to_jsonb(n>0);
  END IF;
  days:=CASE WHEN action='access' THEN ARRAY[today] ELSE ARRAY(SELECT jsonb_array_elements_text(p->'days')) END;
  PERFORM suikan.record(i,v,days);
  IF action='access' THEN
   SELECT jsonb_build_object('schema',1,'allowed',enabled=1,'reason',CASE WHEN enabled=0 THEN reason ELSE '' END)
    INTO result FROM suikan.installation_access WHERE id=i;
   RETURN coalesce(result,jsonb_build_object('schema',1,'allowed',true,'reason',''));
  END IF;
  FOR r IN SELECT value FROM jsonb_array_elements(p->'operations') ORDER BY value->>'day' LOOP
   SELECT to_jsonb(d) INTO old FROM suikan.operation_daily d WHERE d.day=r->>'day' AND d.id=i;
   incoming:=ARRAY(SELECT value::bigint FROM jsonb_array_elements_text((r->'extract')||(r->'summary')));
   delta:=ARRAY[greatest(incoming[1]-coalesce((old->>'extract_started')::bigint,0),0),greatest(incoming[2]-coalesce((old->>'extract_succeeded')::bigint,0),0),greatest(incoming[3]-coalesce((old->>'extract_failed')::bigint,0),0),greatest(incoming[4]-coalesce((old->>'extract_cancelled')::bigint,0),0),greatest(incoming[5]-coalesce((old->>'summary_started')::bigint,0),0),greatest(incoming[6]-coalesce((old->>'summary_succeeded')::bigint,0),0),greatest(incoming[7]-coalesce((old->>'summary_failed')::bigint,0),0),greatest(incoming[8]-coalesce((old->>'summary_cancelled')::bigint,0),0)];
   IF EXISTS(SELECT 1 FROM unnest(delta) x WHERE x>0) THEN
    INSERT INTO suikan.operation_totals AS t(id,extract_started,extract_succeeded,extract_failed,extract_cancelled,summary_started,summary_succeeded,summary_failed,summary_cancelled) VALUES(i,delta[1],delta[2],delta[3],delta[4],delta[5],delta[6],delta[7],delta[8])
     ON CONFLICT(id) DO UPDATE SET extract_started=t.extract_started+excluded.extract_started,extract_succeeded=t.extract_succeeded+excluded.extract_succeeded,extract_failed=t.extract_failed+excluded.extract_failed,extract_cancelled=t.extract_cancelled+excluded.extract_cancelled,summary_started=t.summary_started+excluded.summary_started,summary_succeeded=t.summary_succeeded+excluded.summary_succeeded,summary_failed=t.summary_failed+excluded.summary_failed,summary_cancelled=t.summary_cancelled+excluded.summary_cancelled;
    INSERT INTO suikan.operation_daily AS d(day,id,extract_started,extract_succeeded,extract_failed,extract_cancelled,summary_started,summary_succeeded,summary_failed,summary_cancelled) VALUES(r->>'day',i,incoming[1],incoming[2],incoming[3],incoming[4],incoming[5],incoming[6],incoming[7],incoming[8])
     ON CONFLICT(day,id) DO UPDATE SET extract_started=greatest(d.extract_started,excluded.extract_started),extract_succeeded=greatest(d.extract_succeeded,excluded.extract_succeeded),extract_failed=greatest(d.extract_failed,excluded.extract_failed),extract_cancelled=greatest(d.extract_cancelled,excluded.extract_cancelled),summary_started=greatest(d.summary_started,excluded.summary_started),summary_succeeded=greatest(d.summary_succeeded,excluded.summary_succeeded),summary_failed=greatest(d.summary_failed,excluded.summary_failed),summary_cancelled=greatest(d.summary_cancelled,excluded.summary_cancelled);
   END IF;
  END LOOP;
  RETURN 'null'::jsonb;
 ELSIF action='prune' THEN
  PERFORM pg_advisory_xact_lock(-832640012439001::bigint);
  IF NOT EXISTS(SELECT 1 FROM suikan.maintenance WHERE id=1 AND prune_day>=today) THEN
   DELETE FROM suikan.active WHERE day<to_char(today::date-89,'YYYY-MM-DD');
   DELETE FROM suikan.operation_daily WHERE day<to_char(today::date-89,'YYYY-MM-DD');
   INSERT INTO suikan.maintenance VALUES(1,today) ON CONFLICT(id) DO UPDATE SET prune_day=excluded.prune_day;
  END IF;
  RETURN 'null'::jsonb;
 ELSIF action='installations' THEN
  q:=p->>'q'; lim:=(p->>'limit')::integer; off:=(p->>'offset')::integer;
  RETURN jsonb_build_object('total',(SELECT count(*) FROM suikan.installations WHERE q='' OR (id>=q AND id<q||'g')),
   'offset',off,'limit',lim,'items',coalesce((SELECT jsonb_agg(item ORDER BY last_day DESC,first_day DESC,id) FROM (
    SELECT i.id,i.first_day,i.last_day,jsonb_build_object('id',i.id,'first_day',i.first_day,'last_day',i.last_day,
     'app_version',i.app_version,'enabled',coalesce(a.enabled,1)=1,'reason',coalesce(a.reason,''),
     'usage',suikan.metrics(coalesce(to_jsonb(t),jsonb_build_object('extract_started',0,'extract_succeeded',0,'extract_failed',0,'extract_cancelled',0,'summary_started',0,'summary_succeeded',0,'summary_failed',0,'summary_cancelled',0)))) item
    FROM suikan.installations i LEFT JOIN suikan.installation_access a ON i.id=a.id LEFT JOIN suikan.operation_totals t ON i.id=t.id
    WHERE q='' OR (i.id>=q AND i.id<q||'g') ORDER BY i.last_day DESC,i.first_day DESC,i.id LIMIT lim OFFSET off
   ) s),'[]'::jsonb));
 ELSIF action='summary' THEN
  start:=to_char(today::date-29,'YYYY-MM-DD');
  RETURN (WITH a AS (SELECT day,count(*) n FROM suikan.active WHERE day BETWEEN start AND today GROUP BY day),
   fresh AS (SELECT first_day AS day,count(*) n FROM suikan.installations WHERE first_day BETWEEN start AND today GROUP BY first_day),
   ops AS (SELECT day,coalesce(sum(extract_started),0) AS extract_started,coalesce(sum(extract_succeeded),0) AS extract_succeeded,coalesce(sum(extract_failed),0) AS extract_failed,coalesce(sum(extract_cancelled),0) AS extract_cancelled,coalesce(sum(summary_started),0) AS summary_started,coalesce(sum(summary_succeeded),0) AS summary_succeeded,coalesce(sum(summary_failed),0) AS summary_failed,coalesce(sum(summary_cancelled),0) AS summary_cancelled FROM suikan.operation_daily WHERE day BETWEEN start AND today GROUP BY day),
   dates AS (SELECT to_char(today::date-29+x,'YYYY-MM-DD') AS day FROM generate_series(0,29) x)
   SELECT jsonb_build_object('timezone','Asia/Shanghai','date',today,
    'total_installations',(SELECT count(*) FROM suikan.installations),'new_today',(SELECT count(*) FROM suikan.installations WHERE first_day=today),
    'dau',(SELECT count(*) FROM suikan.active WHERE day=today),'mau_30d',(SELECT count(DISTINCT id) FROM suikan.active WHERE day BETWEEN start AND today),
    'daily',(SELECT jsonb_agg(jsonb_build_object('day',d.day,'active',coalesce(a.n,0),'new',coalesce(fresh.n,0),
      'usage',suikan.metrics(coalesce(to_jsonb(ops),jsonb_build_object('extract_started',0,'extract_succeeded',0,'extract_failed',0,'extract_cancelled',0,'summary_started',0,'summary_succeeded',0,'summary_failed',0,'summary_cancelled',0)))) ORDER BY d.day)
      FROM dates d LEFT JOIN a ON d.day=a.day LEFT JOIN fresh ON d.day=fresh.day LEFT JOIN ops ON d.day=ops.day),
    'versions',coalesce((SELECT jsonb_agg(to_jsonb(s) ORDER BY installations DESC,version) FROM
      (SELECT app_version version,count(*) installations FROM suikan.installations GROUP BY app_version) s),'[]'::jsonb),
    'operations',jsonb_build_object('total',(SELECT suikan.metrics(to_jsonb(s)) FROM (SELECT coalesce(sum(extract_started),0) AS extract_started,coalesce(sum(extract_succeeded),0) AS extract_succeeded,coalesce(sum(extract_failed),0) AS extract_failed,coalesce(sum(extract_cancelled),0) AS extract_cancelled,coalesce(sum(summary_started),0) AS summary_started,coalesce(sum(summary_succeeded),0) AS summary_succeeded,coalesce(sum(summary_failed),0) AS summary_failed,coalesce(sum(summary_cancelled),0) AS summary_cancelled FROM suikan.operation_totals) s),
      'today',(SELECT suikan.metrics(to_jsonb(s)) FROM (SELECT coalesce(sum(extract_started),0) AS extract_started,coalesce(sum(extract_succeeded),0) AS extract_succeeded,coalesce(sum(extract_failed),0) AS extract_failed,coalesce(sum(extract_cancelled),0) AS extract_cancelled,coalesce(sum(summary_started),0) AS summary_started,coalesce(sum(summary_succeeded),0) AS summary_succeeded,coalesce(sum(summary_failed),0) AS summary_failed,coalesce(sum(summary_cancelled),0) AS summary_cancelled FROM suikan.operation_daily WHERE day=today) s))));
 ELSE RAISE EXCEPTION 'Unsupported statistics action';
 END IF;
END $$;
